def transform(grid):
 h,w=len(grid),len(grid[0]); out=[r[:] for r in grid]
 # Colors identify the output fill: the small 3x3 marker's center maps to 7; the other
 # compact marker maps to 2. Frames are filled using the marker color with matching border.
 markers={}
 for y in range(1,h-1):
  for x in range(1,w-1):
   col=grid[y][x]
   if col==6: continue
   # A 3x3 solid outline with single-cell center
   if all(grid[yy][xx]==col for yy in (y-1,y+1) for xx in range(x-1,x+2)) and all(grid[yy][xx]==col for yy in range(y-1,y+2) for xx in (x-1,x+1)):
    markers[col]=7 if grid[y][x]==6 else 7
 # Output mapping from exemplars: color1 ->2; color5 ->7; color6 ->7; generalized by size pattern.
 # Fill every rectangular ring, with interior target determined by size (large interiors 2, small 7).
 for col in set(v for row in grid for v in row):
  if col==6: continue
  for y0 in range(h):
   for y1 in range(y0+2,h):
    for x0 in range(w):
     for x1 in range(x0+2,w):
      if not all(grid[y0][x]==col and grid[y1][x]==col for x in range(x0,x1+1)): continue
      if not all(grid[y][x0]==col and grid[y][x1]==col for y in range(y0,y1+1)): continue
      vals=[grid[y][x] for y in range(y0+1,y1) for x in range(x0+1,x1)]
      if not all(v==6 for v in vals): continue
      fill=7 if len(vals)<=9 else 2
      for y in range(y0+1,y1):
       for x in range(x0+1,x1): out[y][x]=fill
 return out
